    if not data:
        return
    t = int(data[0])
    pair_close = {"(": ")", "[": "]", "{": "}"}
    out = []
    for idx in range(1, t + 1):
        s = data[idx]
        st = []
        ok = True
        for ch in s:
            expected = pair_close.get(ch)
            if expected is not None:
                st.append(expected)
            else:
                if not st or st[-1] != ch:
                    ok = False
                    break
                st.pop()
        out.append("YES" if ok and not st else "NO")
    sys.stdout.write("\n".join(out) + "\n")


