import sys


def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    a = [int(x) for x in data[2 : n + 2]]

    dq = deque()
    sum_max = 0
    min_of_max = None
    for i, val in enumerate(a):
        while dq and dq[0] <= i - k:
            dq.popleft()
        while dq and a[dq[-1]] <= val:
            dq.pop()
        dq.append(i)
        if i >= k - 1:
            cur = a[dq[0]]
            sum_max += cur
            if min_of_max is None or cur < min_of_max:
                min_of_max = cur
    sys.stdout.write(f"{sum_max} {min_of_max}\n")


