    k = int(data[1])
    w = int(data[2])
    projects = []
    idx = 3
    for _ in range(n):
        c = int(data[idx])
        p = int(data[idx + 1])
        projects.append((c, p))
        idx += 2
    projects.sort(key=lambda x: x[0])

    max_heap = []
    ptr = 0
    for _ in range(k):
        while ptr < n and projects[ptr][0] <= w:
            heapq.heappush(max_heap, -projects[ptr][1])
            ptr += 1
        if not max_heap:
            break
        w += -heapq.heappop(max_heap)
    sys.stdout.write(f"{w}\n")


